"""YAML renderer. Standard library only -- see CONTRIBUTING.md."""

import re

from plugins import PluginError, Renderer, register

# Strings that YAML would misread as booleans, nulls, or numbers if left plain.
_RESERVED = {
    "true", "false", "null", "yes", "no", "on", "off", "~",
    "nan", "inf", "-inf", "+inf", ".nan", ".inf",
}

_NUMBER = re.compile(
    r"^[-+]?(\d+\.?\d*|\.\d+)([eE][-+]?\d+)?$|^0[xob][0-9a-fA-F]+$"
)

_LEADING_INDICATORS = set("-?:,[]{}#&*!|>'\"%@`")


def _plain_safe(value: str) -> bool:
    """True if the string can be emitted unquoted and still parse back as a string."""
    if not value or value != value.strip():
        return False
    if value[0] in _LEADING_INDICATORS:
        return False
    if ": " in value or " #" in value or value.endswith(":"):
        return False
    if value.lower() in _RESERVED:
        return False
    if _NUMBER.match(value):
        return False
    return True


def _double_quote(value: str) -> str:
    out = []
    for ch in value:
        if ch == "\\":
            out.append("\\\\")
        elif ch == '"':
            out.append('\\"')
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\t":
            out.append("\\t")
        elif ch == "\r":
            out.append("\\r")
        elif ord(ch) < 0x20 or ord(ch) == 0x7F:
            out.append(f"\\u{ord(ch):04x}")
        else:
            out.append(ch)
    return '"' + "".join(out) + '"'


def _scalar(value) -> str:
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        if value != value:
            return ".nan"
        if value == float("inf"):
            return ".inf"
        if value == float("-inf"):
            return "-.inf"
        return repr(value)
    if isinstance(value, str):
        return value if _plain_safe(value) else _double_quote(value)
    raise PluginError(f"yaml cannot render value of type {type(value).__name__}")


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")
        lines = []
        for row in rows:
            if not row:
                raise PluginError("yaml rows must be non-empty dicts")
            for key, value in row.items():
                if not isinstance(key, str):
                    raise PluginError("yaml keys must be strings")
                lines.append(f"- {_scalar(key)}: {_scalar(value)}")
        return "\n".join(lines) + "\n"

