"""YAML renderer. Standard library only -- see CONTRIBUTING.md."""

from plugins import PluginError, Renderer, register

# Characters that make a plain (unquoted) YAML scalar unsafe.
_UNSAFE_CHARS = set(":#{}[],&*!|>'\"%@`")


def _looks_like_non_string(s: str) -> bool:
    """True if s would be parsed back as something other than a string."""
    low = s.lower()
    if low in {"true", "false", "yes", "no", "on", "off", "null", "~"}:
        return True
    try:
        int(s, 0)
        return True
    except ValueError:
        pass
    try:
        float(s)
        return True
    except ValueError:
        pass
    return False


def _double_quote(s: str) -> str:
    out = []
    for ch in s:
        if ch == "\\":
            out.append("\\\\")
        elif ch == '"':
            out.append('\\"')
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\t":
            out.append("\\t")
        elif ch == "\r":
            out.append("\\r")
        elif ord(ch) < 0x20 or ch == "\x7f":
            out.append("\\x%02x" % ord(ch))
        else:
            out.append(ch)
    return '"' + "".join(out) + '"'


def _scalar(value) -> str:
    """Render one scalar value as a YAML scalar."""
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return repr(value)
    if isinstance(value, str):
        if (
            value
            and value == value.strip()
            and not any(c in _UNSAFE_CHARS for c in value)
            and ": " not in value
            and " #" not in value
            and not _looks_like_non_string(value)
        ):
            return value
        return _double_quote(value)
    raise PluginError(
        "yaml cannot render value of type %s" % type(value).__name__
    )


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")
        lines = []
        for row in rows:
            first = True
            for key, value in row.items():
                prefix = "- " if first else "  "
                lines.append("%s%s: %s" % (prefix, _scalar(key), _scalar(value)))
                first = False
        return "\n".join(lines) + "\n"

