from plugins import PluginError, Renderer, register

# Strings that YAML would parse as something other than a string.
_AMBIGUOUS = {"null", "true", "false", "yes", "no", "on", "off", "~"}
# Characters that may not start a plain scalar.
_INDICATORS = set("-?:,[]{}#&*!|>'\"%@` \t")


def _double_quote(s: str) -> str:
    out = []
    for ch in s:
        if ch == "\\":
            out.append("\\\\")
        elif ch == '"':
            out.append('\\"')
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\t":
            out.append("\\t")
        elif ch == "\r":
            out.append("\\r")
        elif ord(ch) < 0x20:
            out.append(f"\\x{ord(ch):02x}")
        else:
            out.append(ch)
    return '"' + "".join(out) + '"'


def _needs_quoting(s: str) -> bool:
    if s == "" or s != s.strip():
        return True
    if s[0] in _INDICATORS:
        return True
    if ": " in s or s.endswith(":") or " #" in s:
        return True
    if s.lower() in _AMBIGUOUS:
        return True
    try:
        float(s)
    except ValueError:
        return False
    return True


def _scalar(value) -> str:
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return repr(value)
    if isinstance(value, str):
        return _double_quote(value) if _needs_quoting(value) else value
    raise PluginError(f"yaml cannot render value of type {type(value).__name__}")


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")
        lines = []
        for r in rows:
            if not r:
                lines.append("- {}")
                continue
            first = True
            for k, v in r.items():
                if not isinstance(k, str):
                    raise PluginError("yaml keys must be strings")
                prefix = "- " if first else "  "
                first = False
                key = _double_quote(k) if _needs_quoting(k) else k
                lines.append(f"{prefix}{key}: {_scalar(v)}")
        return "\n".join(lines) + "\n"

